const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
const token = auth.slice(7);
try {
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id');
  const body = $input.first().json.body || {};
  const projectId = (body.project_id || '').trim();
  if (!projectId) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'project_id requerido' } }];
  const clientText = (body.client_text || '').trim();
  if (!clientText) return [{ json: { _error: 'VALIDATION_FAILED', _status: 400, _details: 'client_text requerido (lo que dijo el cliente: email, chat, transcripcion reunion)' } }];
  if (clientText.length > 4000) return [{ json: { _error: 'TEXT_TOO_LONG', _status: 413, _details: 'client_text max 4000 chars (recibidos ' + clientText.length + '). Trocear en fragmentos.' } }];
  const validMetodos = ['email','firma_digital','reunion','chat','otro'];
  const metodo = validMetodos.includes(body.metodo_confirmacion) ? body.metodo_confirmacion : 'chat';
  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    project_id: projectId,
    client_text: clientText,
    contexto_propuesta: body.contexto_propuesta || null,
    metodo_confirmacion: metodo,
    evidencia_url: body.evidencia_url || null,
    request_id: 'req_' + Math.random().toString(36).slice(2, 10)
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Validate').first().json;
const projectRows = $('Load Project').all().map(i => i.json).filter(p => p && p.id);
if (projectRows.length === 0) return [{ json: { _error: 'PROJECT_NOT_FOUND', _status: 404, _details: 'project_id no existe', request_id: sess.request_id }}];
const project = projectRows[0];
const briefingRows = $('Load Briefing').all().map(i => i.json).filter(b => b && b.id);
const prevDecisionRows = $('Load Previous Decisions').all().map(i => i.json).filter(d => d && d.id);
const costRows = $input.all().map(i => i.json).filter(c => c && c.id);
const briefing = briefingRows[0] || null;
const cost = costRows[0] || null;

const prevDecisionsText = prevDecisionRows.length
  ? prevDecisionRows.map(function(d) { return '- [' + (d.decision_tipo || 'otro') + ' / ' + (d.confirmada_cliente ? 'confirmada' : 'pendiente') + '] ' + (d.decision_descripcion || '').slice(0, 200) + ' (impacto ' + (d.impacto_economico || 0) + ' EUR, ' + (d.impacto_plazo_dias || 0) + ' dias, ' + d.fecha_decision + ')'; }).join('\n')
  : '(sin decisiones previas registradas)';

const contextoPropuesta = sess.contexto_propuesta
  ? (typeof sess.contexto_propuesta === 'string' ? sess.contexto_propuesta : JSON.stringify(sess.contexto_propuesta))
  : '(no aportado)';

const systemPrompt = 'Eres agent_client_translator. Tu rol: convertir comunicacion natural del cliente (email/chat/transcripcion reunion) en una DECISION FORMAL ESTRUCTURADA. Anti scope-creep. Cada decision es inmutable - se registra con timestamp.\n\nREGLAS DE ORO:\n- Si el texto NO contiene una decision clara (cliente solo pregunta o conversa), devuelve has_decision=false con razon.\n- Si SI hay decision, identifica: decision_tipo (CHECK constraint), descripcion concisa, impacto economico estimado en EUR, impacto plazo en dias, contradicciones con decisiones previas listadas.\n- decision_tipo valido: distribucion, material, presupuesto, plazo, acabados, equipamiento, otro.\n- IMPACTO ECONOMICO: si el cliente pide algo que afecta presupuesto (ej. "quiero porcelanico premium en vez del medio"), estima el delta en EUR (positivo = sube coste).\n- IMPACTO PLAZO: dias adicionales si la decision retrasa obra (ej. "esperemos a que llegue el material X" -> +N dias).\n- CONTRADICCIONES: si la nueva decision choca con una previa confirmada, listala con id + razon.\n- DEVUELVE SOLO JSON valido.';

const userPrompt = 'PROYECTO: ' + project.name + ' (' + project.project_type + ', ' + (project.property_area_m2 || '?') + ' m2, budget ' + (project.budget_target || '?') + ' EUR, fase ' + project.current_phase + ')\n\n' +
  'BRIEFING: ' + (briefing && briefing.summary ? briefing.summary.slice(0, 500) : '(sin briefing)') + '\n\n' +
  'COST ESTIMATE: ' + (cost ? 'v' + cost.version + ', total ' + cost.total_estimated + ' EUR, deviation ' + cost.deviation_status : '(sin cost estimate)') + '\n\n' +
  'CONTEXTO QUE SE PROPUSO AL CLIENTE: ' + contextoPropuesta + '\n\n' +
  'DECISIONES PREVIAS REGISTRADAS (' + prevDecisionRows.length + '):\n' + prevDecisionsText + '\n\n' +
  'TEXTO DEL CLIENTE (' + sess.metodo_confirmacion + '):\n' + sess.client_text + '\n\n' +
  'TAREA: analiza si hay decision, extraela formalmente, calcula impactos, detecta contradicciones.\n\n' +
  'OUTPUT JSON estricto:\n' +
  '{ "has_decision": true, "razon_sin_decision": null, "decision_tipo": "material", "decision_descripcion": "...", "contexto_propuesta": { ... } | null, "impacto_economico": 1500, "impacto_plazo_dias": 7, "contradicciones": [ { "decision_id": "uuid", "razon": "..." } ], "confidence": 0.85, "resumen_para_arquitecto": "..." }';

return [{ json: {
  user_id: sess.user_id,
  tenant_id: sess.tenant_id,
  project_id: project.id,
  request_id: sess.request_id,
  client_text: sess.client_text,
  contexto_propuesta: sess.contexto_propuesta,
  metodo_confirmacion: sess.metodo_confirmacion,
  evidencia_url: sess.evidencia_url,
  llm_payload: {
    model: 'gpt-4o',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt }
    ],
    temperature: 0.1,
    max_tokens: 1500,
    response_format: { type: 'json_object' }
  }
}}];

const llm = $input.first()?.json;
const built = $('Build Prompt').first().json;
const raw = llm?.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) {
  return [{ json: { _error: 'LLM_INVALID_JSON', _status: 502, _details: e.message, _raw: raw.slice(0, 500), request_id: built.request_id }}];
}
const usage = llm?.usage || {};
const validTipos = ['distribucion','material','presupuesto','plazo','acabados','equipamiento','otro'];
const tipo = validTipos.includes(parsed.decision_tipo) ? parsed.decision_tipo : 'otro';
return [{ json: {
  user_id: built.user_id,
  tenant_id: built.tenant_id,
  project_id: built.project_id,
  request_id: built.request_id,
  client_text: built.client_text,
  contexto_propuesta: built.contexto_propuesta,
  metodo_confirmacion: built.metodo_confirmacion,
  evidencia_url: built.evidencia_url,
  output: {
    has_decision: !!parsed.has_decision,
    razon_sin_decision: parsed.razon_sin_decision || null,
    decision_tipo: tipo,
    decision_descripcion: parsed.decision_descripcion || null,
    contexto_propuesta: parsed.contexto_propuesta || built.contexto_propuesta || null,
    impacto_economico: typeof parsed.impacto_economico === 'number' ? parsed.impacto_economico : null,
    impacto_plazo_dias: typeof parsed.impacto_plazo_dias === 'number' ? parsed.impacto_plazo_dias : null,
    contradicciones: Array.isArray(parsed.contradicciones) ? parsed.contradicciones : [],
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : null,
    resumen_para_arquitecto: parsed.resumen_para_arquitecto || null
  },
  summary: {
    has_decision: !!parsed.has_decision,
    decision_tipo: tipo,
    impacto_economico: typeof parsed.impacto_economico === 'number' ? parsed.impacto_economico : null,
    contradicciones_count: (Array.isArray(parsed.contradicciones) ? parsed.contradicciones.length : 0)
  },
  model: llm?.model || 'gpt-4o',
  tokens_in: usage.prompt_tokens || 0,
  tokens_out: usage.completion_tokens || 0
}}];

