const fmt = $('Format Response').first().json;
const inserted = $('Insert Decision').isExecuted ? ($('Insert Decision').first()?.json || null) : null;
return [{ json: {
  data: {
    project_id: fmt.project_id,
    decision_id: inserted ? inserted.id : null,
    fecha_decision: inserted ? inserted.fecha_decision : null,
    output: fmt.output,
    summary: fmt.summary
  },
  meta: {
    request_id: fmt.request_id,
    model: fmt.model,
    tokens_in: fmt.tokens_in,
    tokens_out: fmt.tokens_out,
    eu_ai_act: 'formalizacion no vinculante; el arquitecto valida antes de confirmada_cliente=true'
  }
}}];
